function enterChapter(next){sfx('horn_call',{gain:.6});if(next===5){say('musa_intro',{priority:3,delay:1.4});say('boss',{priority:3,delay:6.4});}else say('chapter',{chance:.75,delay:.4});zone=next;checkpoint=next;p.x=Math.max(p.x,chapters[next].start+100);if(next===4){horseMounted=false;horseCompleted=true;horseX=24580;p.x=24630;}p.hp=p.maxHp;p.energy=100;p.wine=Math.max(2,p.wine);p.invuln=2;lastSafe=p.x;arrows=[];save();toast('Kontrolna tačka · napredak sačuvan',3);speak(chapters[zone].message);sound('magic');fx('flash','#ffd890',.1);}
function attackActive(){const d=attackDuration();if(p.attackKind==='super')return p.attack>0&&p.attack<d*.5&&p.attack>d*.18;return p.attack>0&&p.attack<d*.58&&p.attack>d*.12;}
